/* v36 지역 의뢰: 마을마다 잡기 · 모으기 · 특수 의뢰 · 지역 특색 의뢰 하나(sig) — q36/*.js 를 합친 것 (q36/make.sh) */
// MID — written for v36
const Q36_MID_FOLK={};
const Q36_MID_SQ=[
 // ── 골드미어 (황금 평원) ──
 {id:'q36_goldmere_1',town:'goldmere',giver:'gm_corwin',lvl:25,kind:'추적',t:'밀밭에 난 늑대 길',say:'밀밭 한가운데에 밀대가 동그랗게 눕혀진 자리가 생겼어. 늑대 무리가 누워 쉬다 간 자리야. 거기서부터 짐승 길이 남쪽 들판으로 이어지더군. 순찰대는 수확 수레 지키느라 손이 없으니, 네가 그 길을 따라가서 무리를 이끄는 놈을 찾아 줘.',done:'흉터 귀 녀석이었군. 그놈이 쓰러졌으니 무리도 한동안 흩어져 다닐 거야. 순찰대 몫으로 받아 둬.',
  goals:[{type:'track',reg:'plains',steps:[[110,700,'밀대가 동그랗게 눕혀져 있다. 짐승 털이 아직 따뜻하다'],[120,1100,'이삭이 짓밟힌 좁은 길. 발자국이 넷, 다섯… 무리다'],[170,1450,'허수아비가 쓰러져 있다. 옷자락에 이빨 자국이 났다'],[175,1800,'낮은 언덕 너머에서 길게 우는 소리가 들린다!']],foe:'p_wolf',foeN:'흉터 귀 늑대 우두머리',d:'눕혀진 밀대 따라가 늑대 우두머리 찾기',n:5}],rw:{xp:.9,gold:163,pot:2}},
 {id:'q36_goldmere_2',town:'goldmere',giver:'gm_nim',lvl:27,kind:'수수께끼',t:'베르타 할머니의 들판 수수께끼',say:'베르타 할머니가 바람에도 이름이 있다고 했잖아요. 할머니한테 들은 들판 수수께끼가 세 개 있는데, 저 혼자서는 하나도 못 맞혔어요. 같이 풀어 줄래요? 다 맞히면 동네 애들한테 자랑할 거예요!',done:'와, 다 맞혔어요! 이제 할머니한테 가서 제가 푼 척해도 되죠? …농담이에요. 이건 제가 모은 동전이에요.',
  goals:[{type:'riddle',npc:'gm_nim',qs:[['날개는 있는데 날지 못하고, 바람이 불면 하루 종일 돌기만 해요. 나는 무엇일까요?',['허수아비','풍차','연'],1],['봄에 심으면 여름엔 초록, 가을엔 금빛이 되고, 겨울엔 빵이 되어 식탁에 올라요. 나는 무엇일까요?',['밀','사과','갈대'],0],['밤새 들판에 서 있지만 잠도 안 자고 밥도 안 먹어요. 새들은 나를 무서워하지만 나는 아무도 해치지 못해요. 나는 무엇일까요?',['순찰대원','늑대','허수아비'],2]],d:'꼬마 님이 내는 들판 수수께끼 셋 풀기',n:3}],rw:{xp:.9,gold:181,pot:2}},
 {id:'q36_goldmere_3',town:'goldmere',giver:'gm_berta',lvl:30,kind:'지키기',sig:1,t:'폭풍 오는 밤의 큰 풍차',say:'코윈 말이 그룸바가 울었다는구나. 오늘 밤 큰 폭풍이 온다는 뜻이야. 북동쪽 언덕의 큰 풍차 날개를 접고 축에 쐐기를 박아야 하는데, 그사이 폭풍 정령이랑 약탈 기사들이 풍차를 노리고 몰려들 거야. 일이 끝날 때까지 풍차 곁에서 버텨 주렴. 풍차가 쓰러지면 처음부터 다시 해야 해.',done:'날개가 무사하구나! 이 풍차가 서 있는 한 골드미어는 숨을 쉰단다. 고맙다, 정말 고마워.',
  goals:[{type:'defend',reg:'plains',at:[320,1100],secs:75,hp:360,mobs:['p_storm','p_raider','p_wolf'],what:'큰 풍차',d:'폭풍이 오는 75초 동안 큰 풍차 지키기'}],rw:{xp:1.2,gold:210,pot:3,tp:1}},
 // ── 엘드홀트 (고목의 숲) ──
 {id:'q36_elderhold_1',town:'elderhold',giver:'el_orein',lvl:27,kind:'추격',t:'덫을 놓는 밀렵꾼',say:'고목 아래 덫을 놓고 다니는 밀렵꾼을 방금 야영지 앞에서 봤어. 날 보자마자 덫 꾸러미를 메고 숲 동쪽으로 내달렸지. 저놈이 놓은 덫에 새끼 사슴이 셋이나 다쳤다. 따라잡아서 꾸러미째 데려와 줘.',done:'덫이 스무 개나 들어 있었다니… 이걸 다 숲에 깔았으면 어쩔 뻔했어. 이놈은 내가 숲 밖으로 데려다주지.',
  goals:[{type:'chase',reg:'forest',at:[20,650],path:[[15,950],[10,1250],[75,1450],[5,1700],[75,1500]],who:{n:'밀렵꾼 갈스',L:{body:'#4a4a2a',legs:'#2a2a1a',cape:'#5a5030',hair:'#6a4a2a',hs:3,hat:3,hatC:'#3a3a22'}},d:'덫 꾸러미를 멘 밀렵꾼 갈스 붙잡기'}],rw:{xp:.9,gold:181,pot:2}},
 {id:'q36_elderhold_2',town:'elderhold',giver:'el_muna',lvl:29,kind:'지키기',t:'해독약 솥이 끓는 동안',say:'포자 덩어리에 숨이 막힌 사람이 야영지에 둘이나 누워 있단다. 해독약은 숲 남쪽 샘가에서 고목 수액을 넣고 오래 끓여야 하는데, 끓는 냄새를 맡고 짐승들이 몰려들어. 샘가에 솥을 걸어 둘 테니, 약이 다 될 때까지 솥을 지켜 주렴.',done:'약이 진하게 우러났구나. 두 사람 다 오늘 밤엔 편히 숨 쉬겠어. 남은 약은 네 몫이다.',
  goals:[{type:'defend',reg:'forest',at:[100,900],secs:60,hp:348,mobs:['f_slime','f_were','f_golem'],what:'해독약 솥',d:'해독약 솥을 60초 동안 지키기'}],rw:{xp:1.1,gold:200,pot:3,tp:1}},
 {id:'q36_elderhold_3',town:'elderhold',giver:'el_taren',lvl:32,kind:'봉인',sig:1,t:'고목 넷의 나이테 노래',say:'숲의 고목들은 뿌리로 노래를 주고받아. 그런데 타락한 숲 정령들이 그 노래를 끊어 놨어. 서쪽 숲에 백 년, 삼백 년, 오백 년, 천 년 된 고목이 하나씩 서 있지. 노래는 언제나 어린 나무가 먼저 부르고 늙은 나무가 받는 법이야. 그 차례대로 나무껍질에 손을 얹어 줘. 차례가 틀리면 노래가 엉키고 숲 정령이 깨어날 거야.',done:'들려? 발밑에서 웅웅 울리는 소리. 숲이 다시 노래하고 있어. 고목들이 너한테 고맙다고 할 거야… 아마 내 입을 빌려서.',
  goals:[{type:'ritual',reg:'forest',stones:[[200,750,'삼백 년 고목'],[245,1350,'천 년 고목'],[225,650,'백 년 고목'],[190,1150,'오백 년 고목']],order:[2,0,3,1],hint:'어린 나무부터 늙은 나무 순서로',mobs:['f_dryad','f_golem'],d:'고목 넷을 어린 나무부터 늙은 나무 순서로 깨우기'}],rw:{xp:1.2,gold:230,pot:3,tp:1}},
 // ── 사하르 오아시스 (붉은 사막) ──
 {id:'q36_sahar_1',town:'sahar',giver:'sh_ilan',lvl:33,kind:'수수께끼',t:'향료상의 덤 수수께끼',say:'향료를 사고팔려면 코보다 머리가 먼저 돌아가야 해요. 우리 집안 장사꾼들은 손님한테 수수께끼 셋을 내고, 다 맞히면 덤을 얹어 줬죠. 한번 도전해 보시겠어요? 냄새도 공짜, 물음도 공짜예요.',done:'세 개 다! 손님은 장사꾼 해도 되겠어요. 약속대로 덤이에요. 사프란은… 아, 그건 안 돼요. 대신 금화로 드릴게요.',
  goals:[{type:'riddle',npc:'sh_ilan',qs:[['물 없이도 열흘을 걷고, 등에 작은 산을 지고 다녀요. 대상 행렬은 나 없이는 못 떠나요. 나는 무엇일까요?',['낙타','전갈','모래 정령'],0],['금보다 비싼 붉은 실. 꽃 한 송이에서 겨우 세 가닥만 나와요. 나는 무엇일까요?',['계피','사프란','몰약'],1],['모래 위에 남지만 바람이 불면 사라지고, 걸어간 사람 뒤에만 생겨요. 나는 무엇일까요?',['신기루','물주머니','발자국'],2]],d:'향료상 일란이 내는 수수께끼 셋 풀기',n:3}],rw:{xp:.9,gold:241,pot:2}},
 {id:'q36_sahar_2',town:'sahar',giver:'sh_mehra',lvl:35,kind:'지키기',t:'옛 우물을 다시 여는 날',say:'오아시스 동쪽에 우리 할머니의 할머니가 쓰던 옛 우물이 모래에 묻혀 있어요. 일꾼들이 그 우물을 다시 파는데, 땅을 파면 모래 속에 잠든 것들이 깨어나요. 물길이 뚫릴 때까지 우물 도르래를 지켜 주세요. 도르래가 부서지면 처음부터 다시 파야 해요.',done:'물이 올라와요! 옛 우물이 다시 숨을 쉬어요. 이 물은 당신한테는 평생 공짜예요.',
  goals:[{type:'defend',reg:'desert',at:[20,1000],secs:60,hp:420,mobs:['d_sand','d_scorp','d_mummy'],what:'옛 우물 도르래',d:'물길이 뚫릴 60초 동안 우물 도르래 지키기'}],rw:{xp:1.1,gold:263,pot:3,tp:1}},
 {id:'q36_sahar_3',town:'sahar',giver:'sh_zarin',lvl:37,kind:'추적',sig:1,t:'모래바람이 지우기 전에',say:'새벽 모래바람에 대상 행렬 끝의 낙타 한 마리가 짐째 사라졌네. 모래바람은 발자국을 반나절이면 다 지워 버리지. 지금이라면 남쪽 모래 언덕에 아직 흔적이 남아 있을 걸세. 끊기기 전에 따라가 주게. 그 낙타 등에 실린 건 이번 여행의 물값 전부야.',done:'낙타가 살아 있다니! 짐도 거의 그대로야. 열두 마리가 열두 마리로 돌아왔으니, 이번 여행은 아주 좋은 여행이군.',
  goals:[{type:'track',reg:'desert',steps:[[80,700,'모래 위에 낙타 발자국. 바람이 벌써 가장자리를 무너뜨리고 있다'],[100,1100,'끊어진 고삐 끈. 발자국 옆에 여러 갈래 집게 자국이 섞였다'],[95,1500,'반쯤 묻힌 물주머니. 둘레 모래가 붉게 물들어 있다'],[115,1850,'모래 언덕 아래에서 딱딱한 껍질이 부딪히는 소리가 난다!']],foe:'d_scorp',foeN:'낙타를 끌고 간 모래 집게',d:'지워지는 낙타 발자국 따라가기',n:5}],rw:{xp:1.2,gold:285,pot:3,tp:1}},
 // ── 프로스트헤임 (북부 빙원) ──
 {id:'q36_frostheim_1',town:'frostheim',giver:'fh_brynja',lvl:37,kind:'추격',t:'장작 썰매를 끌고 간 사람',say:'내가 하루 종일 팬 장작을 썰매째 끌고 간 놈이 있어! 털모자 쓴 떠돌이였는데, 지금 막 마을 서쪽 눈밭으로 달아났어. 눈이 깊어서 멀리는 못 갔을 거야. 따라잡아서 썰매를 돌려받아 줘. 오늘 밤 장작이 없으면 집 세 채가 얼어.',done:'썰매도 장작도 멀쩡하네. 그 떠돌이, 자기도 얼어 죽을 것 같아서 그랬대. 장작 한 단은 나눠 줬어. 그래도 도둑은 도둑이지!',
  goals:[{type:'chase',reg:'ice',at:[190,650],path:[[205,950],[175,1250],[215,1450],[190,1700],[160,1450]],who:{n:'털모자 떠돌이 하쿤',L:{body:'#6a5a4a',legs:'#3a3030',cape:'#8a7a6a',hair:'#c8a878',hs:3,hat:5,hatC:'#a89a8a'}},d:'장작 썰매를 끌고 달아난 하쿤 붙잡기'}],rw:{xp:.9,gold:285,pot:2}},
 {id:'q36_frostheim_2',town:'frostheim',giver:'fh_saga',lvl:39,kind:'봉인',t:'금 간 룬돌 다시 새기기',say:'빙원 북쪽에 내가 세운 룬돌 넷이 있단다. 그중 하나가 보랏빛으로 금이 가더니, 나머지까지 빛이 약해졌어. 룬돌은 하루가 흐르듯 새벽, 한낮, 해질녘, 한밤 순서로 새겨야 힘이 이어진단다. 이 늙은이 다리로는 못 가니, 네가 그 차례대로 돌에 손을 대 주렴.',done:'룬돌이 다시 파랗게 숨을 쉬는구나. 금 간 자리는 남았지만, 얼음이 그 기억을 품어 줄 게다. 고맙다.',
  goals:[{type:'ritual',reg:'ice',stones:[[300,1000,'해질녘 룬돌'],[330,800,'새벽 룬돌'],[290,1400,'한밤 룬돌'],[350,1250,'한낮 룬돌']],order:[1,3,0,2],hint:'하루가 흐르는 순서대로, 새벽에서 한밤까지',mobs:['i_wraith','i_elem'],d:'룬돌 넷을 새벽부터 한밤까지 하루 순서로 새기기'}],rw:{xp:1.1,gold:308,pot:3,tp:1}},
 {id:'q36_frostheim_3',town:'frostheim',giver:'fh_kalle',lvl:41,kind:'추적',sig:1,t:'눈사람을 돌려놓는 발자국',say:'제가 만든 눈사람이 또 방향이 바뀌었어요! 이번엔 옆에 자국이 남아 있었어요. 사람 발은 아니고, 얼음 조각을 꾹꾹 찍은 것 같은 동그란 자국이요. 오드바르 아저씨는 바람 탓이래요. 바람은 발자국을 안 남기잖아요! 먼저 따라가 주세요. 저는 여기서 망볼게요.',done:'얼음 정령이었어요? 눈사람이 부러워서 흉내 내다가 제 걸 자꾸 돌려놨던 거군요. 이제 제 눈사람은 계속 바다 쪽을 볼 거예요. 이건 제가 아끼는 얼음 구슬이에요!',
  goals:[{type:'track',reg:'ice',steps:[[50,650,'눈사람 둘레에 동그란 얼음 자국이 빙 돌아 찍혀 있다'],[10,1050,'얼어붙은 개울 위로 자국이 이어진다. 밟힌 자리마다 얼음이 더 두꺼워졌다'],[20,1400,'눈사람이 또 하나! 누군가 흉내 내어 만든 듯 삐뚤빼뚤하다'],[10,1800,'눈보라 사이로 반짝이는 무언가가 키득거린다!']],foe:'i_elem',foeN:'눈사람을 흉내 내는 얼음 정령',d:'동그란 얼음 자국 따라가 눈사람 장난꾼 찾기',n:5}],rw:{xp:1.2,gold:332,pot:3,tp:1}},
 // ── 타말 신전촌 (타말 정글) ──
 {id:'q36_tamal_1',town:'tamal',giver:'tm_paco',lvl:41,kind:'추적',t:'노란 눈을 따라가요',say:'어젯밤 오두막 뒤 덤불에서 노란 눈 두 개가 저를 쳐다봤어요! 아침에 가 보니까 진흙에 커다란 발자국이 있었고, 닭장 문도 긁혀 있었어요. 아하르 아저씨는 북만 치고 제 말은 안 믿어요. 발자국 따라가서 진짜 표범인지 봐 주세요!',done:'진짜 표범이었죠? 제 말이 맞았죠?! 이제 아하르 아저씨한테 자랑하러 갈래요. 이건 제 보물 주머니에서 꺼낸 거예요!',
  goals:[{type:'track',reg:'jungle',steps:[[300,700,'덤불 아래 진흙에 둥근 발바닥 자국. 발톱 자국은 없다'],[320,1050,'나무줄기에 높이 긁힌 자국. 사람 키보다 높다'],[285,1450,'덩굴에 걸린 검은 털 뭉치. 밤처럼 까맣다'],[305,1800,'나뭇잎 그늘 속에서 노란 눈 두 개가 번쩍 뜨인다!']],foe:'j_panther',foeN:'노란 눈의 그림자 표범',d:'진흙 발자국 따라가 노란 눈의 주인 찾기',n:5}],rw:{xp:.9,gold:332,pot:2}},
 {id:'q36_tamal_2',town:'tamal',giver:'tm_chera',lvl:43,kind:'수수께끼',t:'신전 계단에 새긴 물음',say:'신전 돌계단 끝마다 옛 신관들이 새긴 물음이 있단다. 덩굴을 걷어 내니 세 개가 겨우 읽히더구나. 옛날엔 이 물음에 답해야 신전에 들어갈 수 있었지. 이 늙은이와 함께 풀어 보겠니?',done:'세 물음 다 풀었구나. 옛 신관들이 봤으면 신전 문을 활짝 열어 줬을 게다. 내가 대신 이걸 주마.',
  goals:[{type:'riddle',npc:'tm_chera',qs:[['비가 오면 커지고 가뭄이 오면 작아져요. 늘 아래로만 흘러 신전 앞을 지나가요. 나는 무엇일까요?',['강','덩굴','그림자'],0],['두드리면 울고, 울면 사람들이 모여요. 이 마을에서는 정글의 심장이라고 불러요. 나는 무엇일까요?',['종','북','피리'],1],['올라갈수록 줄어들고, 다 오르고 나면 하나도 남지 않아요. 나는 무엇일까요?',['촛불','덩굴','남은 계단'],2]],d:'신전지기 체라와 계단의 물음 셋 풀기',n:3}],rw:{xp:.9,gold:357,pot:2}},
 {id:'q36_tamal_3',town:'tamal',giver:'tm_ahar',lvl:45,kind:'봉인',sig:1,t:'숲이 대답하는 북',say:'북을 쳐도 숲이 대답을 안 해. 정글 서남쪽에 옛사람들이 세운 북 넷이 있는데, 소리를 삼키는 것이 그 북들을 막아 버렸어. 정글의 북은 언제나 가장 낮은 소리부터 쳐서 가장 높은 소리로 끝내야 해. 땅이 먼저 깨고, 하늘이 나중에 듣는 거지. 소리가 낮은 것부터 차례로 두드려 줘.',done:'들었어? 저 멀리서 둥, 하고 숲이 대답했어! 몇 달 만이야. 오늘 밤은 마을 전체가 북을 칠 거야. 너도 와서 한 번 쳐.',
  goals:[{type:'ritual',reg:'jungle',stones:[[130,750,'가장 낮은 통나무 북'],[175,1350,'가장 높은 대나무 북'],[165,1000,'조금 높은 뼈 북'],[95,1200,'조금 낮은 가죽 북']],order:[0,3,2,1],hint:'낮은 소리에서 높은 소리로. 땅이 먼저, 하늘이 나중',mobs:['j_lizard','j_golem'],d:'옛 북 넷을 낮은 소리부터 높은 소리 순서로 울리기'}],rw:{xp:1.2,gold:383,pot:3,tp:1}},
 // ── 엠버홀드 (잿불 용암지대) ──
 {id:'q36_emberhold_1',town:'emberhold',giver:'eh_gusta',lvl:47,kind:'추격',t:'전우들 이름이 새겨진 훈장',say:'젊을 적 바깥 성벽에서 받은 훈장을 술잔 옆에 잠깐 내려놨는데, 낯선 녀석이 그걸 채서 남문 밖으로 내달렸어. 녹여서 쇳값이나 받을 셈이겠지. 그 훈장엔 바깥 성벽과 함께 묻힌 내 전우들 이름이 새겨져 있네. 이 늙은 다리로는 못 쫓아가. 부탁하네.',done:'이름이 하나도 안 지워졌군… 고맙네. 그 녀석은 하드렐에게 넘겼어. 성벽 보수나 한 달 시키면 정신 차리겠지. 자, 한잔은 내가 사지.',
  goals:[{type:'chase',reg:'lava',at:[100,650],path:[[110,950],[85,1250],[100,1450],[100,1700],[80,1450]],who:{n:'잿빛 망토 도둑 렌',L:{body:'#5a4a44',legs:'#2a2020',cape:'#6a6060',hair:'#1a1210',hs:0,hat:2,hatC:'#3a3030'}},d:'훈장을 채 간 도둑 렌 붙잡기'}],rw:{xp:.9,gold:409,pot:2}},
 {id:'q36_emberhold_2',town:'emberhold',giver:'eh_seren',lvl:49,kind:'수수께끼',t:'불꽃이 묻는 말',say:'불꽃을 읽는 법을 배우고 싶다는 사람은 많지만, 먼저 불이 내는 물음에 답할 줄 알아야 해요. 제 스승이 저에게 냈던 물음 셋을 그대로 낼게요. 불 앞에서 서두르면 데요. 천천히 생각하세요.',done:'세 개 다 맞혔네요. 불꽃이 당신 쪽으로 기울었어요. 불이 당신을 좋아한다는 뜻이에요.',
  goals:[{type:'riddle',npc:'eh_seren',qs:[['먹을 것을 주면 살고, 물을 주면 죽어요. 나는 무엇일까요?',['불','이끼','바람'],0],['불로 녹이고 얼음으로 다스려야 날이 서는, 이 땅의 검은 유리는 무엇일까요?',['수정','흑요석','강철'],1],['뜨거울 때는 붉게 흐르지만, 식으면 검고 단단한 땅이 돼요. 성벽 밖을 흐르는 나는 무엇일까요?',['연기','재','용암'],2]],d:'불길 점술사 세렌이 내는 물음 셋에 답하기',n:3}],rw:{xp:.9,gold:436,pot:2}},
 {id:'q36_emberhold_3',town:'emberhold',giver:'eh_hadrel',lvl:51,kind:'지키기',sig:1,t:'금 간 흑요석 방벽',say:'서쪽 바깥 방벽에 금이 갔다. 틸라가 녹인 흑요석을 부어 틈을 메우는 동안, 용암 냄새를 맡은 놈들이 그 틈으로 몰려들 거다. 흑요석이 굳을 때까지 방벽을 지켜라. 방벽이 무너지면 틀을 다시 짜고 처음부터 부어야 한다. 이 벽 한 장 뒤가 바로 용암이다.',done:'굳었다. 손바닥으로 쳐 봐도 소리가 꽉 찼어. 이 벽은 네 덕에 백 년은 더 간다. 엠버홀드는 이 일을 잊지 않는다.',
  goals:[{type:'defend',reg:'lava',at:[200,800],secs:80,hp:612,mobs:['l_imp','l_elem','l_golem','l_knight'],what:'금 간 흑요석 방벽',d:'흑요석이 굳는 80초 동안 방벽 지키기'}],rw:{xp:1.2,gold:464,pot:3,tp:1}},
 // ── 펄 하버 (산호 군도) ──
 {id:'q36_pearlport_1',town:'pearlport',giver:'pp_kiri',lvl:53,kind:'수수께끼',t:'바닷가 조약돌 수수께끼',say:'달라 언니가 바다 수수께끼를 냈는데 하나도 못 맞혔어요. 다 맞히는 사람한테 진짜 진주를 준다고 약속해 버렸지 뭐예요! …진짜 진주는 없지만 동전은 있어요. 같이 풀어 줄래요?',done:'와, 다 맞혔어요! 약속대로 진짜… 동전이에요. 진주는 제가 크면 꼭 찾아다 드릴게요.',
  goals:[{type:'riddle',npc:'pp_kiri',qs:[['하루에 두 번 오고 하루에 두 번 가요. 올 때는 모래톱을 덮고, 갈 때는 조개를 남겨요. 나는 무엇일까요?',['밀물과 썰물','갈매기','바람'],0],['옆으로만 걷고, 집게가 둘이고, 껍데기는 딱딱해요. 나는 무엇일까요?',['바다뱀','게','해파리'],1],['조개 속에서 아주 오래 자라요. 처음엔 모래 한 알이었지만 나중엔 하얗게 빛나요. 나는 무엇일까요?',['조약돌','소금','진주'],2]],d:'꼬마 키리와 바다 수수께끼 셋 풀기',n:3}],rw:{xp:.9,gold:493,pot:2}},
 {id:'q36_pearlport_2',town:'pearlport',giver:'pp_irene',lvl:55,kind:'지키기',t:'모래톱에 건져 올린 짐',say:'북동쪽 모래톱에 좌초한 상선의 짐을 건지고 있어요. 짐을 다 옮기려면 한참 걸리는데, 그사이 익사자들과 게들이 짐더미로 기어 올라와요. 짐 상자 곁을 지켜 주세요. 상자가 부서지면 짐꾼들이 처음부터 다시 날라야 해요.',done:'상자가 모두 무사해요! 이 짐이 다 팔리면 항구에 한 달은 배가 더 들어올 거예요. 고마워요, 정말로.',
  goals:[{type:'defend',reg:'sea',at:[285,1000],secs:70,hp:660,mobs:['s_drown','s_crab','s_serp'],what:'건져 올린 짐 상자',d:'건진 짐 상자를 70초 동안 지키기'}],rw:{xp:1.1,gold:523,pot:3,tp:1}},
 {id:'q36_pearlport_3',town:'pearlport',giver:'pp_umber',lvl:57,kind:'봉인',sig:1,t:'썰물 길 말뚝',say:'썰물이 되면 항구 남쪽 바다에 섬까지 이어지는 모래길이 드러나지. 옛날엔 그 길에 말뚝을 박아 물이 차오르는 걸 알렸는데, 세이렌 노래에 홀린 놈들이 말뚝 표식을 다 뽑아 놨어. 표식은 물이 빠지는 대로 따라 나가며, 얕은 곳에서 깊은 곳 순서로 다시 걸어야 하네. 거꾸로 걸면 바다가 길을 기억 못 해. 이 늙은 다리 대신 걸어 주게.',done:'보게, 물이 들어오니 말뚝 표식이 하나씩 잠기지. 이제 진주잡이들이 길 위에서 물에 갇힐 일은 없겠어. 바다에 진 빚 하나를 갚은 기분이군.',
  goals:[{type:'ritual',reg:'sea',stones:[[70,1600,'허리 물 말뚝'],[45,1200,'무릎 물 말뚝'],[30,950,'발목 물 말뚝'],[40,700,'마른 모래 말뚝']],order:[3,2,1,0],hint:'물이 빠지는 대로, 얕은 곳에서 깊은 곳으로',mobs:['s_siren','s_drown'],d:'썰물 길 말뚝 넷을 얕은 곳부터 깊은 곳 순서로 다시 걸기'}],rw:{xp:1.2,gold:553,pot:3,tp:1}},
 // ── 까마귀샘 (바람의 황야) ──
 {id:'q36_rookwell_1',town:'rookwell',giver:'rw_osk',lvl:30,kind:'추적',t:'이끼 묻은 발자국',say:'들개 짓이라고만 생각했는데, 오늘 아침 우리 앞에 찍힌 발자국은 들개 것이 아니야. 사람 발보다 세 배는 크고, 이끼가 묻어 있었어. 양 한 마리를 통째로 들고 간 모양이야. 황야 북쪽으로 이어진 그 발자국을 따라가 줘.',done:'양이 살아 있었다니! 트롤이 제 새끼처럼 품고 잤던 거래? 별일이야. 아무튼 이제 셈이 맞네. 고맙네.',
  goals:[{type:'track',reg:'moor',steps:[[250,700,'울타리 밖, 이끼 덩이가 묻은 커다란 발자국'],[270,1100,'양털 뭉치가 가시덤불에 걸려 있다. 핏자국은 없다'],[280,1450,'선돌 하나가 기울어 있다. 무언가 기대어 쉬었던 자국'],[265,1800,'바위 그늘에서 무겁게 코 고는 소리가 들린다!']],foe:'h_troll',foeN:'양을 업어 간 이끼 트롤',d:'이끼 묻은 발자국 따라가 양 도둑 찾기',n:5}],rw:{xp:.9,gold:210,pot:2}},
 {id:'q36_rookwell_2',town:'rookwell',giver:'rw_wenna',lvl:32,kind:'추격',t:'술값 떼먹은 떠돌이 악사',say:'사흘을 먹고 마시고 노래만 부르던 떠돌이 악사가 방금 술값도 안 내고 뒷문으로 내뺐어! 남쪽 황야 길로 갔어. 돈도 돈이지만, 그 녀석이 우리 주막 이끼술 비법 쪽지까지 들고 갔다고. 잡아 오면 한 잔은 평생 공짜야.',done:'비법 쪽지도 돌아왔고, 술값은 노래 열 곡으로 갚기로 했어. 생각해 보니 노래는 잘하더라. 약속대로 넌 평생 한 잔 공짜야.',
  goals:[{type:'chase',reg:'moor',at:[100,650],path:[[120,950],[90,1250],[135,1450],[110,1700],[80,1500]],who:{n:'떠돌이 악사 토울',L:{body:'#6a3a5a',legs:'#3a2a32',cape:'#8a5a7a',hair:'#c8a060',hs:2,hat:3,hatC:'#4a2a3a'}},d:'술값을 떼먹은 떠돌이 악사 토울 붙잡기'}],rw:{xp:.9,gold:230,pot:2}},
 {id:'q36_rookwell_3',town:'rookwell',giver:'rw_maud',lvl:34,kind:'수수께끼',sig:1,t:'선돌 틈의 속삭임',say:'선돌은 세는 게 아니란다. 대신 들어야 하지. 밤마다 돌 틈에서 죽은 이들이 물음을 속삭이는데, 산 사람이 대답해 주면 그날 밤엔 잠을 잘 잔다는구나. 요즘 속삭임이 부쩍 늘었어. 이 할멈이 받아 적은 물음 셋에 답해 주련?',done:'돌 틈이 조용해졌어. 오늘 밤 죽은 이들은 대답을 듣고 푹 잘 게다. 너도 잘 자려무나. 이건 선돌지기가 대대로 건네던 몫이다.',
  goals:[{type:'riddle',npc:'rw_maud',qs:[['산 사람은 하루에도 수만 번 쉬지만 아무도 세지 않아요. 죽은 이가 가장 그리워하는 것이지요. 나는 무엇일까요?',['숨','금화','선돌'],0],['많이 부를수록 멀리 가지만, 돌아오는 건 언제나 내 목소리뿐이에요. 황야 바위에 부딪혀 돌아오는 나는 무엇일까요?',['까마귀','메아리','망령'],1],['물로 되어 있지만 손에 잡히지 않아요. 황야를 덮으면 선돌도 길도 보이지 않고, 해가 뜨면 사라져요. 나는 무엇일까요?',['들개','이끼','안개'],2]],d:'선돌지기 모드가 받아 적은 물음 셋에 답하기',n:3}],rw:{xp:1.2,gold:252,pot:3,tp:1}},
 // ── 바람목 산채 (서리바람 고원) ──
 {id:'q36_windcrag_1',town:'windcrag',giver:'wc_tomi',lvl:35,kind:'지키기',t:'뿔돌이네 염소 우리',say:'산 아래 풀밭에 염소들을 몰고 내려왔는데, 잿빛 곰 냄새가 나요! 염소들은 겁이 나서 우리 안에서 꼼짝도 안 해요. 해가 산을 넘을 때까지만 염소 우리를 지켜 주세요. 그러면 다 같이 산채로 올라갈 수 있어요. 뿔돌이도 같이요!',done:'한 마리도 안 다쳤어요! 뿔돌이가 고맙다고 머리로 받으려고 해요. 그게 고맙다는 뜻이에요, 진짜로요.',
  goals:[{type:'defend',reg:'highland',at:[75,900],secs:60,hp:420,mobs:['k_bear','k_harpy','k_rogue'],what:'염소 우리',d:'염소 우리를 60초 동안 지키기'}],rw:{xp:1.1,gold:263,pot:3,tp:1}},
 {id:'q36_windcrag_2',town:'windcrag',giver:'wc_bera',lvl:37,kind:'추격',t:'석 달 말린 치즈 바퀴',say:'이번엔 하피가 아니라 사람이 치즈를 훔쳐 갔어요! 산을 버린 사람 하나가 제일 잘 익은 치즈 바퀴를 안고 서쪽 비탈로 뛰어 내려갔어요. 바람에 석 달을 말린 거예요. 쫓아가서 꼭 돌려받아 주세요.',done:'치즈가 멀쩡해요! 한 귀퉁이 베어 먹은 자국이 있긴 한데… 맛있었나 봐요. 이 조각은 당신 몫이에요. 독한 술이랑 같이 드세요.',
  goals:[{type:'chase',reg:'highland',at:[200,650],path:[[185,950],[205,1250],[170,1450],[195,1700],[210,1450]],who:{n:'산을 버린 사내 고르',L:{body:'#5a5048',legs:'#3a3028',cape:'#7a6a5a',hair:'#3a2a1a',hs:3,hat:1,hatC:'#4a4038'}},d:'치즈 바퀴를 안고 달아난 고르 붙잡기'}],rw:{xp:.9,gold:285,pot:2}},
 {id:'q36_windcrag_3',town:'windcrag',giver:'wc_dalmo',lvl:39,kind:'봉인',sig:1,t:'능선 봉화 올리기',say:'고원 북쪽 능선에는 골짜기 아래부터 꼭대기까지 봉화대 넷이 있다. 눈보라 무당들이 그걸 다 꺼 버려서, 산채끼리 소식을 못 전하고 있지. 봉화는 불이 산을 타고 오르듯 아랫목부터 꼭대기로 차례로 붙여야 한다. 꼭대기부터 붙이면 아래에선 아무도 못 본다. 아랫목, 중턱, 어깨, 꼭대기. 순서 잊지 마라.',done:'봐라, 저 위 산채에서도 불이 올랐다. 이제 소식이 다시 산을 탄다. 바람이 법인 곳에서 불을 지켰으니, 넌 이 산채 사람이나 다름없다.',
  goals:[{type:'ritual',reg:'highland',stones:[[340,700,'아랫목 봉화'],[300,1700,'꼭대기 봉화'],[320,1000,'중턱 봉화'],[285,1350,'어깨 봉화']],order:[0,2,3,1],hint:'산 아래에서 꼭대기로. 아랫목, 중턱, 어깨, 꼭대기',mobs:['k_shaman','k_harpy'],d:'봉화 넷을 산 아래부터 꼭대기 순서로 올리기'}],rw:{xp:1.2,gold:308,pot:3,tp:1}},
 // ── 먼지문 (망각의 협곡) ──
 {id:'q36_dustgate_1',town:'dustgate',giver:'dg_pip',lvl:39,kind:'추격',t:'발굴 지도를 채 간 도적',say:'하스카 아줌마가 맡긴 발굴 지도를 잠깐 펼쳐 봤는데, 협곡 도적 하나가 휙 낚아채서 달아났어요! 그 지도엔 아직 아무도 안 판 거인 무덤 자리가 다 적혀 있어요. 아줌마가 알면 저 정식 발굴꾼 못 돼요… 제발 도와주세요!',done:'지도다! 구김도 없어요. 아줌마한텐 비밀이에요, 네? 대신 제가 주운 거인 손톱… 아니 돌이랑, 이건 진짜 동전이요.',
  goals:[{type:'chase',reg:'canyon',at:[150,650],path:[[165,950],[160,1250],[175,1450],[165,1700],[100,1450]],who:{n:'협곡 도적 스쿠',L:{body:'#7a5a3a',legs:'#3a2a1a',cape:'#a8865a',hair:'#2a1a10',hs:0,hat:3,hatC:'#6a4a2a'}},d:'발굴 지도를 채 간 도적 스쿠 붙잡기'}],rw:{xp:.9,gold:308,pot:2}},
 {id:'q36_dustgate_2',town:'dustgate',giver:'dg_ottel',lvl:41,kind:'지키기',t:'파수 인형 태엽 감기',say:'협곡 북쪽에 쓰러진 고대 파수 인형 하나를 우리 편으로 돌려놓을 수 있을 것 같아. 거인 태엽을 끝까지 감는 데 시간이 꽤 걸리는데, 감는 소리에 먼지 회오리랑 갈퀴벌레가 몰려들 거야. 태엽이 다 감길 때까지 인형 곁을 지켜 줘. 인형이 부서지면 처음부터야.',done:'눈에 불이 들어왔어! 이 녀석은 이제 먼지문 쪽을 지켜 줄 거야. 천 년 묵은 톱니가 이렇게 잘 돌다니, 거인들은 정말 기막혀.',
  goals:[{type:'defend',reg:'canyon',at:[280,1000],secs:75,hp:492,mobs:['c_dust','c_scorp','c_bandit'],what:'태엽을 감는 파수 인형',d:'태엽이 다 감기는 75초 동안 파수 인형 지키기'}],rw:{xp:1.1,gold:332,pot:3,tp:1}},
 {id:'q36_dustgate_3',town:'dustgate',giver:'dg_haska',lvl:43,kind:'수수께끼',sig:1,t:'성문 터의 거인 비문',say:'성문 터에서 거인들 비문이 새겨진 돌판이 나왔어. 거인들은 문 앞에 물음을 새기고, 답을 아는 자만 들였다지. 글자는 내가 다 풀었는데 답은 모르겠어. 셋 다 맞히면 이 돌판은 우리 발굴단이 처음으로 끝까지 읽은 거인의 말이 되는 거야.',done:'다 읽었어! 마지막 줄은 「답을 아는 자여, 들어오라」였어. 천 년 만에 누군가 그 문 앞에 선 거야. 이건 발굴단 몫에서 떼어 주는 거다.',
  goals:[{type:'riddle',npc:'dg_haska',qs:[['나는 이가 많지만 아무것도 씹지 않아요. 서로 맞물려 돌면 거인의 문이 열려요. 나는 무엇일까요?',['톱니바퀴','빗','갈퀴벌레'],0],['천 년을 서 있어도 지치지 않고, 오는 이를 막고 가는 이를 보내요. 열쇠를 보면 길을 비켜 주는 나는 무엇일까요?',['파수병','성문','협곡'],1],['물 한 잔이 금 한 닢인 이 협곡에서, 거인들도 집보다 먼저 판 것. 깊을수록 시원한 나는 무엇일까요?',['무덤','보물고','우물'],2]],d:'발굴단장 하스카와 거인 비문의 물음 셋 풀기',n:3}],rw:{xp:1.2,gold:357,pot:3,tp:1}},
 // ── 갈매기 등대 (폭풍 절벽) ──
 {id:'q36_gullhaven_1',town:'gullhaven',giver:'gh_torben',lvl:45,kind:'지키기',t:'그물 말리는 덕장',say:'새로 엮은 그물을 남쪽 벼랑 위 덕장에 널어 말리는 중이야. 그물이 마를 때까지만 버티면 되는데, 하피 놈들이 또 찢으러 몰려올 게 뻔해. 이번엔 한 올도 못 찢게 덕장 곁을 지켜 줘. 덕장이 무너지면 그물을 다시 널어야 해.',done:'한 올도 안 찢겼어! 이 그물이면 다음 철 고기는 걱정 없겠어. 내 손가락도 오늘은 좀 쉬겠군.',
  goals:[{type:'defend',reg:'cliffs',at:[90,950],secs:65,hp:540,mobs:['t_harpy','t_drake'],what:'그물 덕장',d:'그물이 마르는 65초 동안 덕장 지키기'}],rw:{xp:1.1,gold:383,pot:3,tp:1}},
 {id:'q36_gullhaven_2',town:'gullhaven',giver:'gh_moi',lvl:47,kind:'봉인',t:'벼락받이 쇠말뚝',say:'오르뎀 할아버지가 북쪽 벼랑에 쇠말뚝 넷을 박아 두셨어요. 번개를 대신 맞아서 등대를 지켜 주는 말뚝이요. 그런데 폭풍 숭배자들이 말뚝 고리를 다 풀어 놨어요. 번개는 언제나 바다 쪽에서 오니까, 바다에 가장 가까운 말뚝부터 등대 쪽으로 차례로 고리를 걸어야 한대요. 저 대신 걸어 주실래요?',done:'방금 번개가 바다 끝 말뚝에 떨어졌어요! 등불은 멀쩡해요. 할아버지가 저보고 오늘 일은 잘했대요. 사실 당신이 한 거지만요.',
  goals:[{type:'ritual',reg:'cliffs',stones:[[280,1750,'바다 끝 말뚝'],[285,1050,'벼랑 중간 말뚝'],[340,1400,'파도 바위 말뚝'],[280,700,'등대 밑 말뚝']],order:[0,2,1,3],hint:'번개는 바다에서 온다. 바다에서 가장 가까운 말뚝부터 등대 쪽으로',mobs:['t_sentinel','t_cultist'],d:'벼락받이 말뚝 넷을 바다 쪽부터 등대 쪽으로 차례로 걸기'}],rw:{xp:1.1,gold:409,pot:3,tp:1}},
 {id:'q36_gullhaven_3',town:'gullhaven',giver:'gh_ivka',lvl:49,kind:'추적',sig:1,t:'바람에 실린 쇳내',say:'바람에 쇳내가 섞였어요. 누군가 벼랑 어딘가에서 번개를 부르고 있다는 뜻이에요. 냄새는 바람을 거슬러 가면 근원에 닿아요. 지금 바람은 북쪽에서 불어요. 쇳내가 짙어지는 쪽으로 따라가서, 번개를 부르는 자를 찾아 주세요.',done:'바람이 맑아졌어요. 쇳내가 사라졌어요. 이제 남쪽 바람의 낯선 냄새만 남았네요… 그건 다음에 읽을게요. 고마워요.',
  goals:[{type:'track',reg:'cliffs',steps:[[300,700,'쇳내가 코끝을 찌른다. 바위에 검게 그을린 자국'],[285,1100,'번개 맞은 갈매기 둥지. 깃털이 아직 타닥거린다'],[305,1450,'바위에 그린 폭풍 문양. 소금과 재를 섞어 그렸다'],[295,1850,'벼랑 끝에서 누군가 하늘을 향해 외치고 있다!']],foe:'t_cultist',foeN:'번개를 부르는 폭풍 사제',d:'쇳내를 거슬러 가 번개를 부르는 자 찾기',n:5}],rw:{xp:1.2,gold:436,pot:3,tp:1}},
 // ── 마지막 등불 (심연의 균열) ──
 {id:'q36_lastlight_1',town:'lastlight',giver:'ll_gurt',lvl:55,kind:'추적',t:'균열 쪽으로 끌린 자국',say:'밤 경계 때 초소 바깥 첫 등불 아래에 긴 자국이 남았어. 무언가 무거운 쇠붙이를 끌고 균열 쪽으로 간 자국이야. 그러고 보니 무기고에서 갑옷 한 벌이 없어졌더군. 자국을 따라가서 그걸 걸치고 다니는 놈이 누군지 알아내 줘.',done:'우리 갑옷을 걸치고 다녔다고? 다음엔 초소병 흉내까지 냈겠군. 소름 끼치는데. 덕분에 큰일 날 뻔한 걸 막았다.',
  goals:[{type:'track',reg:'abyss',steps:[[60,700,'첫 등불 아래, 쇠를 끈 긴 자국. 가장자리에 보랏빛 서리가 앉았다'],[80,1100,'떨어진 투구 깃. 초소의 보라 깃이다'],[50,1450,'바위에 남은 손자국. 손가락이 사람보다 하나 더 많다'],[70,1850,'균열 가장자리에서 초소 갑옷을 걸친 무언가가 돌아본다!']],foe:'v_knight',foeN:'초소 갑옷을 걸친 공허 기사',d:'쇠를 끈 자국 따라가 갑옷 도둑 찾기',n:5}],rw:{xp:.9,gold:523,pot:2}},
 {id:'q36_lastlight_2',town:'lastlight',giver:'ll_miro',lvl:57,kind:'추격',t:'동그라미가 없는 이름',say:'초소에 온 사람은 누구든 이름을 적어요. 그런데 방금 순례자 한 사람이 이름도 안 적고 균열 쪽으로 걸어 나갔어요. 부르니까 뛰기 시작했고요. 균열 가까이 가면 돌아오지 못해요. 붙잡아서 데려와 주세요. 이름 옆에 동그라미를 쳐야 하니까요.',done:'에다 씨는 균열에서 누가 자기 이름을 불렀대요. 이제 정신이 돌아왔어요. 이름 옆에 동그라미를 쳤어요. 하나 더 늘었네요. 고마워요.',
  goals:[{type:'chase',reg:'abyss',at:[300,650],path:[[285,950],[340,1250],[275,1450],[275,1700],[350,1450]],who:{n:'홀린 순례자 에다',L:{body:'#5a5068',legs:'#2a2632',cape:'#8a7aa0',hair:'#d8d4cc',hs:2,hat:5,hatC:'#3a3048'}},d:'균열로 걸어가는 순례자 에다 붙잡기'}],rw:{xp:.9,gold:553,pot:2}},
 {id:'q36_lastlight_3',town:'lastlight',giver:'ll_tesal',lvl:59,kind:'봉인',sig:1,t:'균열까지 이어진 등불',say:'초소에서 균열 가장자리까지 등불 넷이 줄지어 서 있어요. 그림자들이 그걸 다 꺼 버렸어요. 등불은 반드시 초소에서 가까운 것부터 균열 쪽으로 차례로 켜야 해요. 뒤에 켜진 불빛이 앞 불을 받쳐 주거든요. 균열 코앞 등불부터 켜면 어둠이 그 불을 바로 삼켜 버려요. 빛이끼 기름은 제가 드릴게요.',done:'불빛이 균열까지 한 줄로 이어졌어요. 저 끝에서 그림자가 물러나는 게 보여요. 이 불은 제가 꺼지지 않게 지킬게요. 약속해요.',
  goals:[{type:'ritual',reg:'abyss',stones:[[150,1050,'초소에서 백 걸음 등불'],[165,1800,'균열 코앞 등불'],[135,650,'초소 문 앞 등불'],[140,1400,'균열에서 백 걸음 등불']],order:[2,0,3,1],hint:'초소에서 가까운 등불부터 균열 쪽으로',mobs:['v_shade','v_maw','v_seer'],d:'등불 넷을 초소에서 가까운 것부터 균열 쪽으로 켜기'}],rw:{xp:1.2,gold:584,pot:3,tp:1}},
];

// HIGH — written for v36
const Q36_HIGH_FOLK={};
const Q36_HIGH_SQ=[
/* ===== 달물결 쉼터 (h29_reed) ===== */
{id:'q36_h29_reed_camp_1',town:'h29_reed_camp',giver:'r30_osen',lvl:71,kind:'처치',t:'밧줄 끊는 집게',say:'요 며칠 아침마다 나루 밧줄이 싹둑싹둑 잘려 있네. 범인은 달물결 갑각수들이야. 밤물에 올라와 그 큰 집게로 밧줄을 끊고, 풀려난 배를 장난감처럼 뒤집어 놓지. 쉼터 동쪽 물가에서 녀석들 수를 좀 줄여 주게.',done:'오늘 아침엔 밧줄이 한 가닥도 안 끊겼더군! 배들이 얌전히 물 위에 떠 있는 걸 보니 이제야 숨이 쉬어지네.',
 goals:[{type:'kill',k:['h29_reed_1'],n:10,d:'나루 밧줄을 끊는 달물결 갑각수 10마리 처치'}],rw:{xp:1,gold:788,pot:2}},
{id:'q36_h29_reed_camp_2',town:'h29_reed_camp',giver:'r30_yuna',lvl:73,kind:'수집',t:'피리에 붙일 얇은 막',say:'갈대 피리는 대롱에 아주 얇은 막을 붙여야 맑게 떨려요. 보통은 갈대 속껍질을 쓰지만, 갈대 비늘 사냥수의 지느러미막은 그보다 훨씬 얇고 질겨요. 사냥수를 잡으면 가끔 찢기지 않은 막이 남아요. 여섯 장만 모아 주세요. 쉼터 아이들 피리를 새로 만들어 주고 싶어요.',done:'와, 비쳐 보일 만큼 얇아요! 한번 불어 볼게요… 들리세요? 바람이 반, 숨이 반. 이 소리예요.',
 goals:[{type:'collect',k:['h29_reed_0'],p:.5,n:6,item:'얇은 지느러미막',d:'갈대 비늘 사냥수에게서 얇은 지느러미막 6장 모으기'}],rw:{xp:.8,gold:825,pot:2}},
{id:'q36_h29_reed_camp_3',town:'h29_reed_camp',giver:'r30_osen',lvl:76,kind:'봉인',sig:1,t:'달을 닮은 나루돌',say:'갈대벌 물길 곳곳에 달 모양이 새겨진 옛 나루돌이 넷 있네. 이 벌판의 물은 달을 따라 차고 빠지니, 옛 나루지기들은 나루돌도 달이 자라는 순서대로 깨웠지. 가느다란 초승달이 반쪽짜리 상현달로 자라고, 둥근 보름달로 꽉 찼다가, 다시 그믐달로 이우는 차례야. 순서를 어기면 물이 거꾸로 흘러 안개 속 것들이 몰려올 걸세.',done:'물길이 제 방향으로 흐르기 시작했네! 오늘 밤엔 달물결이 나루까지 은빛으로 밀려오겠군. 자네 덕에 옛 나루가 다시 숨을 쉬네.',
 goals:[{type:'ritual',reg:'h29_reed',stones:[[320,900,'보름달 나루돌'],[20,1300,'초승달 나루돌'],[60,800,'그믐달 나루돌'],[340,1500,'상현달 나루돌']],order:[1,3,0,2],hint:'초승달 · 상현달 · 보름달 · 그믐달 (달이 차올랐다가 이우는 순서)',mobs:['h29_reed_2','h29_reed_3'],d:'달 나루돌 넷을 달이 자라고 이우는 순서대로 깨우기'}],rw:{xp:1.2,gold:882,pot:3,tp:1}},

/* ===== 유리길 초소 (h29_kiln) ===== */
{id:'q36_h29_kiln_camp_1',town:'h29_kiln_camp',giver:'k30_dan',lvl:70,kind:'처치',t:'가짜 길등',say:'유리길에는 밤길을 밝히는 붉은 길등이 줄지어 서 있어. 그런데 유리등 도마뱀들이 꼬리를 빛내며 길등 흉내를 내는 바람에, 나그네들이 녀석들 불빛을 따라가다 뜨거운 바위 틈으로 빠지곤 해. 초소 둘레 도마뱀들을 잡아 줘. 진짜 불빛만 남게.',done:'어젯밤엔 길을 잃은 나그네가 하나도 없었어. 이제 유리길 불빛은 전부 진짜야. 수고했어.',
 goals:[{type:'kill',k:['h29_kiln_0'],n:10,d:'길등 흉내를 내는 유리등 도마뱀 10마리 처치'}],rw:{xp:1,gold:770,pot:2}},
{id:'q36_h29_kiln_camp_2',town:'h29_kiln_camp',giver:'k30_verka',lvl:74,kind:'수집',t:'꺼지지 않는 불티',say:'붉은 유리에 노을빛을 넣으려면 아주 뜨거운 불티 한 줌이 필요해. 붉은 불티 요정을 쓰러뜨리면 가끔 식지 않는 불티가 남아. 맨손으로 만지지 말고 이 쇠 통에 담아 와. 여섯 알이면 꽃병 하나를 물들일 수 있어.',done:'통이 아직도 따끈하네. 이걸로 구운 유리는 해 질 녘 하늘 같은 빛이 나. 첫 번째 꽃병은 네 몫이야.',
 goals:[{type:'collect',k:['h29_kiln_2'],p:.5,n:6,item:'꺼지지 않는 불티',d:'붉은 불티 요정에게서 꺼지지 않는 불티 6알 모으기'}],rw:{xp:.8,gold:844,pot:2}},
{id:'q36_h29_kiln_camp_3',town:'h29_kiln_camp',giver:'k30_dan',lvl:76,kind:'추적',sig:1,t:'유리로 굳은 발자국',say:'황야에 이상한 발자국이 생겼어. 붉은 모래가 발 모양 그대로 녹아서 유리가 됐더라고. 발바닥이 그만큼 뜨거운 놈이 지나갔다는 뜻이지. 발자국 유리가 아직 식지 않았으니 멀리 못 갔을 거야. 따라가서 정체를 알아내 줘.',done:'숯가마 불을 몸에 품은 방랑 기사였다니… 녀석이 걸어 다닌 자리마다 모래가 유리로 굳어 버렸던 거야. 베르카가 그 발자국 유리를 주워다 장식을 만들겠대.',
 goals:[{type:'track',reg:'h29_kiln',steps:[[300,700,'모래 위에 발 모양 붉은 유리. 손을 대 보니 아직 미지근하다'],[315,1100,'발자국 유리가 점점 맑아진다. 발이 더 뜨거워졌다는 뜻이다'],[330,1450,'바위 하나가 반쯤 녹아 흘러내렸다. 숯 냄새가 짙다'],[320,1800,'눈앞의 모래가 지글지글 끓는다. 무언가 이쪽으로 걸어온다!']],foe:'h29_kiln_1',foeN:'불타는 발의 방랑 기사',d:'유리로 굳은 발자국 따라가 그 주인 찾기',n:5}],rw:{xp:1.2,gold:882,pot:3,tp:1}},

/* ===== 푸른 맥 파수막 (h29_crystal) ===== */
{id:'q36_h29_crystal_camp_1',town:'h29_crystal_camp',giver:'c30_bodo',lvl:81,kind:'처치',t:'설익은 수정을 갉는 벌레',say:'수정은 숲이 내줄 때만 얻는 거라고 했지? 그런데 수정 뿔 벌레들은 그걸 기다리지 않아. 아직 뿌리에서 덜 자란 어린 수정까지 뿔로 쪼아 먹어 버리지. 이대로면 내년엔 숲이 내줄 수정이 하나도 없을 거야. 파수막 남쪽에서 벌레들을 쫓아 줘.',done:'오늘 보니 어린 수정들이 다시 반짝이더군. 저것들이 다 자라면 숲이 또 조금씩 내주겠지. 고맙다.',
 goals:[{type:'kill',k:['h29_crystal_0'],n:10,d:'어린 수정을 갉아 먹는 수정 뿔 벌레 10마리 처치'}],rw:{xp:1,gold:980,pot:2}},
{id:'q36_h29_crystal_camp_2',town:'h29_crystal_camp',giver:'c30_seol',lvl:83,kind:'수집',t:'구슬에 갇힌 마나',say:'푸른 맥 주술사들은 땅속 마나를 빨아올려 작은 구슬에 가둬 두고 다녀요. 그래서 맥이 자꾸 마르는 거예요. 주술사를 쓰러뜨리면 그 구슬이 떨어질 때가 있어요. 여섯 개만 가져다주세요. 구슬을 깨서 마나를 맥으로 돌려보낼게요.',done:'구슬을 하나씩 깰 때마다 발밑에서 맥 소리가 커져요. 들리세요? 숲이 물을 마시는 소리 같아요.',
 goals:[{type:'collect',k:['h29_crystal_2'],p:.5,n:6,item:'마나가 갇힌 구슬',d:'푸른 맥 주술사에게서 마나가 갇힌 구슬 6개 모으기'}],rw:{xp:.8,gold:1021,pot:2}},
{id:'q36_h29_crystal_camp_3',town:'h29_crystal_camp',giver:'c30_seol',lvl:86,kind:'봉인',sig:1,t:'수정 나무에 맥 잇기',say:'숲 한가운데 수정 나무 한 그루가 말라 가고 있어요. 나무 둘레에 뿌리 · 줄기 · 가지 · 잎 이름이 붙은 수정 넷이 박혀 있는데, 마나는 나무의 물처럼 땅에서 올라와야 해요. 뿌리에서 줄기로, 줄기에서 가지로, 가지에서 잎으로. 그 순서대로 손을 대 맥을 이어 주세요. 거꾸로 하면 마나가 터져서 숲 짐승들이 깨어나요.',done:'수정 나무 잎끝까지 푸른빛이 번졌어요! 이제 이 숲의 맥은 저 나무에서부터 다시 뛸 거예요.',
 goals:[{type:'ritual',reg:'h29_crystal',stones:[[80,1500,'줄기 수정'],[160,1000,'잎 수정'],[40,900,'뿌리 수정'],[120,1300,'가지 수정']],order:[2,0,3,1],hint:'뿌리 · 줄기 · 가지 · 잎 (마나가 땅에서 올라가는 순서)',mobs:['h29_crystal_0','h29_crystal_2'],d:'수정 넷을 뿌리부터 잎까지 마나가 오르는 순서대로 잇기'}],rw:{xp:1.2,gold:1084,pot:3,tp:1}},

/* ===== 눈잠 쉼터 (h29_snow) ===== */
{id:'q36_h29_snow_camp_1',town:'h29_snow_camp',giver:'s30_tor',lvl:80,kind:'처치',t:'눈 밑의 덫',say:'눈잠 갑각수들은 순례길 눈 속에 몸을 묻고 잠을 자. 그러다 누가 등을 밟으면 깨어나서 발목을 물어 버리지. 순례자들은 눈만 보고 걷다가 그대로 당하고. 쉼터 앞 순례길을 따라가며 녀석들을 깨워서 잡아 줘.',done:'오늘 지나간 순례자들 발목이 다 멀쩡하더군. 이 길이 다시 걸을 만한 길이 됐어.',
 goals:[{type:'kill',k:['h29_snow_0'],n:10,d:'순례길 눈 속에 숨은 눈잠 갑각수 10마리 처치'}],rw:{xp:1,gold:960,pot:2}},
{id:'q36_h29_snow_camp_2',town:'h29_snow_camp',giver:'s30_amel',lvl:82,kind:'수집',t:'돌아오지 못한 이름들',say:'얼어붙은 순례병들은 원래 우리처럼 성소를 향해 걷던 사람들이었어요. 그들 목에는 아직 이름이 새겨진 나무패가 걸려 있어요. 그분들을 쉬게 해 드리고, 이름패를 가져다주세요. 성소에 가면 제가 그 이름들을 하나하나 불러 드릴게요.',done:'이름패 여섯… 이제 이분들도 함께 성소까지 가시는 거예요. 노래를 하나 더 배워야겠어요. 이름을 부르는 노래로요.',
 goals:[{type:'collect',k:['h29_snow_1'],p:.5,n:6,item:'순례자 이름패',d:'얼어붙은 순례병에게서 순례자 이름패 6개 모으기'}],rw:{xp:.8,gold:1000,pot:2}},
{id:'q36_h29_snow_camp_3',town:'h29_snow_camp',giver:'s30_tor',lvl:85,kind:'추적',sig:1,t:'왼손을 벽에 대고',say:'어젯밤 눈보라에 어린 순례자 하나가 쉼터를 못 찾고 사라졌어. 순례길 규칙은 눈보라가 치면 왼손을 얼음벽에 대고 걷는 거야. 그 아이도 그걸 알 테니, 얼음벽에 남은 작은 손자국을 따라가면 찾을 수 있을 거야. 서둘러. 눈이 손자국을 덮기 전에.',done:'아이가 무사하다니! 서리 무당이 일부러 길을 흐려 놨던 거였군. 그래도 그 녀석, 끝까지 왼손을 떼지 않았대. 순례길 아이답지.',
 goals:[{type:'track',reg:'h29_snow',steps:[[290,700,'얼음벽에 작은 왼손 자국. 손가락 다섯이 또렷하다'],[305,1100,'손자국이 한동안 끊겼다가 다시 이어진다. 눈 위에 작은 발자국도 있다'],[320,1450,'얼음벽에 서리 무늬가 비틀려 있다. 누군가 길을 흐려 놓았다'],[310,1800,'얼음 기둥 뒤에서 아이 울음소리와 서리 무당의 주문 소리가 들린다!']],foe:'h29_snow_2',foeN:'길을 흐리는 서리 무당',d:'얼음벽의 손자국 따라가 사라진 아이 찾기',n:5}],rw:{xp:1.2,gold:1063,pot:3,tp:1}},

/* ===== 종원 지킴터 (h29_bell) ===== */
{id:'q36_h29_bell_camp_1',town:'h29_bell_camp',giver:'b30_garn',lvl:91,kind:'처치',t:'짖지 않는 사냥개',say:'종원 사냥개들은 짖지 않아. 발소리도 안 나지. 이 정원은 소리를 다 삼키니까, 녀석들이 무리 지어 다가와도 아무도 모르는 거야. 어제는 지킴이 하나가 등을 물렸어. 녀석들 무리를 흩어 줘. 소리 대신 눈으로 잘 살피고.',done:'요 며칠은 등 뒤가 덜 서늘하군. 소리 없는 놈들을 소리 없이 해치웠다니, 너도 이 정원에 꽤 익숙해졌나 보다.',
 goals:[{type:'kill',k:['h29_bell_0'],n:10,d:'소리 없이 다가오는 종원 사냥개 10마리 처치'}],rw:{xp:1,gold:1192,pot:2}},
{id:'q36_h29_bell_camp_2',town:'h29_bell_camp',giver:'b30_hesse',lvl:93,kind:'수집',t:'아버지께 드릴 작은 종',say:'깨진 종의 아가리들은 부서진 종 조각을 삼키고 다녀요. 그 배 속에는 옛 종의 청동이 그대로 남아 있대요. 청동 조각을 여섯 개만 모아 주시면, 그걸 녹여서 손바닥만 한 종을 하나 만들고 싶어요. 아버지 손에 쥐여 드리려고요. 혹시 그 종소리를 들으면 다시 말씀을 하실지도 몰라요.',done:'이만큼이면 작은 종 하나는 충분해요. …아버지가 이 조각들을 보시더니 손가락으로 톡 두드리셨어요. 웃으신 것 같았어요.',
 goals:[{type:'collect',k:['h29_bell_2'],p:.5,n:6,item:'옛 종의 청동 조각',d:'깨진 종의 아가리에게서 옛 종의 청동 조각 6개 모으기'}],rw:{xp:.8,gold:1237,pot:2}},
{id:'q36_h29_bell_camp_3',town:'h29_bell_camp',giver:'b30_hesse',lvl:96,kind:'봉인',sig:1,t:'어른 종부터 울려라',say:'정원에는 아버지가 돌보던 종 넷이 아직 기둥에 걸려 있어요. 할아버지 종, 아버지 종, 맏아들 종, 막내 종. 종원에서는 언제나 나이 많은 종이 먼저 울고, 어린 종이 그 뒤를 따라야 한대요. 그 순서대로 종을 깨워 주세요. 순서가 어긋나면 침묵의 것들이 소리를 빼앗으러 몰려와요.',done:'네 종이 차례로 울렸어요! 소리가 정원 끝까지 갔다가… 돌아왔어요. 메아리가 돌아왔어요!',
 goals:[{type:'ritual',reg:'h29_bell',stones:[[150,1100,'맏아들 종'],[40,800,'막내 종'],[100,1500,'할아버지 종'],[70,1050,'아버지 종']],order:[2,3,0,1],hint:'할아버지 종 · 아버지 종 · 맏아들 종 · 막내 종 (나이 많은 종부터)',mobs:['h29_bell_1','h29_bell_3'],d:'종 넷을 나이 많은 종부터 차례로 울리기'}],rw:{xp:1.2,gold:1306,pot:3,tp:1}},

/* ===== 새벽 파수막 (h29_veil) ===== */
{id:'q36_h29_veil_camp_1',town:'h29_veil_camp',giver:'v30_orsa',lvl:92,kind:'처치',t:'봉인석을 갉는 이빨',say:'봉인을 삼키는 짐승들이 봉인석 모서리를 갉아 먹고 있다. 돌이 깎일 때마다 봉인에 금이 하나씩 늘어난다. 루멘 사제가 아무리 새벽빛을 부어도 새는 독에 물 붓기다. 파수막 동쪽 벌판에서 녀석들을 줄여라.',done:'봉인석에 새 이빨 자국이 없다. 금도 더는 늘지 않았고. 잘했다.',
 goals:[{type:'kill',k:['h29_veil_2'],n:8,d:'봉인석 모서리를 갉아 먹는 봉인을 삼키는 짐승 8마리 처치'}],rw:{xp:1,gold:1214,pot:2}},
{id:'q36_h29_veil_camp_2',town:'h29_veil_camp',giver:'v30_lumen',lvl:93,kind:'수집',t:'바랜 새벽빛 모으기',say:'빛바랜 봉인 망령들은 옛날 봉인석에 깃들었던 새벽빛의 찌꺼기예요. 그들을 쉬게 하면 흐린 빛 조각이 남는 때가 있어요. 그 조각을 여섯 개 모아 주세요. 다시 맑게 닦아서 약해진 봉인석에 돌려줄 거예요.',done:'이렇게 흐려도 새벽빛은 새벽빛이에요. 닦으니까 금방 따뜻해지네요. 봉인석들이 좋아할 거예요.',
 goals:[{type:'collect',k:['h29_veil_3'],p:.5,n:6,item:'흐린 새벽빛 조각',d:'빛바랜 봉인 망령에게서 흐린 새벽빛 조각 6개 모으기'}],rw:{xp:.8,gold:1237,pot:2}},
{id:'q36_h29_veil_camp_3',town:'h29_veil_camp',giver:'v30_orsa',lvl:95,kind:'수수께끼',sig:1,t:'새벽 파수의 맹세',say:'새벽 파수가 되려는 자는 봉인석 앞에서 세 물음에 답해야 한다. 순찰대장이 맹세를 저버린 뒤로 이 물음을 다시 꺼낼 일이 없길 바랐지만… 네게라면 묻고 싶다. 천천히 생각하고 답해라.',done:'셋 다 맞혔다. 이제 너도 새벽 파수의 맹세를 아는 사람이다. 이 벌판에서 길을 잃으면 그 맹세를 떠올려라.',
 goals:[{type:'riddle',npc:'v30_orsa',qs:[['해보다 먼저 일어나 해를 깨우는 것. 밤의 끝이자 낮의 시작. 나는 무엇인가?',['노을','새벽','이슬'],1],['말로 하면 한 마디지만 지키는 데는 평생이 걸린다. 깨지면 소리 없이 무엇보다 크게 부서진다. 나는 무엇인가?',['맹세','유리','바람'],0],['빛이 강할수록 더 짙어지고 빛이 없으면 사라진다. 늘 네 곁에 있지만 붙잡을 수 없다. 나는 무엇인가?',['바람','어둠','그림자'],2]],d:'오르사가 묻는 새벽 파수의 물음 셋에 답하기',n:3}],rw:{xp:1.2,gold:1283,pot:3,tp:1}},

/* ===== 옹기여신 성소 (ongi) ===== */
{id:'q36_ongi_camp_1',town:'ongi_camp',giver:'og_koko',lvl:36,kind:'처치',t:'순례길의 진흙투성이',say:'신전 가마에서 흘러나온 가마 진흙덩이들이 눈길 위를 굴러다녀요. 걔네가 지나간 자리는 진흙이 얼어서 미끄럼판이 돼요. 저도 오는 길에 세 번이나 넘어졌다니까요! 성소 둘레 진흙덩이들 좀 치워 주세요.',done:'이제 넘어질 걱정 없겠어요! 바구니에 든 옹기도 무사하고요. 고마워요!',
 goals:[{type:'kill',k:['og_1'],n:8,d:'눈길을 진흙판으로 만드는 가마 진흙덩이 8마리 처치'}],rw:{xp:1,gold:274,pot:2}},
{id:'q36_ongi_camp_2',town:'ongi_camp',giver:'og_mira',lvl:38,kind:'수집',t:'금 간 옹기 조각',say:'설원을 떠도는 깨진 옹기 망령들은 원래 신전에 바쳐졌던 옹기들이에요. 깨진 채 버려졌다는 서러움에 떠도는 거래요. 옹기여신께서는 깨진 옹기도 버리지 않으셨어요. 망령들을 달래 주고 남은 조각을 모아 주세요. 제가 금 간 자리를 흙으로 메워서 다시 신전에 모실게요.',done:'조각이 이만큼이면 항아리 하나는 다시 빚을 수 있겠어요. 금 간 자리가 오히려 무늬처럼 예쁠 거예요. 여신께서 하셨던 것처럼요.',
 goals:[{type:'collect',k:['og_0'],p:.55,n:6,item:'금 간 옹기 조각',d:'깨진 옹기 망령에게서 금 간 옹기 조각 6개 모으기'}],rw:{xp:.8,gold:296,pot:2}},
{id:'q36_ongi_camp_3',town:'ongi_camp',giver:'og_koko',lvl:39,kind:'처치',t:'코만 섬기는 사람들',say:'가짜코 숭배자들 얘기 들었어요? 여신님 말고 그 코만 섬긴대요! 밤마다 성소 동상에 실리콘 코를 덧붙이려고 몰래 다가와요. 도담 언니가 아침마다 떼어 내느라 진땀을 빼요. 성소 근처를 어슬렁거리는 숭배자들을 혼내 주세요.',done:'오늘 아침엔 동상 코가 멀쩡했대요! 도담 언니가 아침부터 웃었어요. 그거면 된 거죠.',
 goals:[{type:'kill',k:['og_3'],n:8,d:'동상에 실리콘 코를 붙이려는 가짜코 숭배자 8명 처치'}],rw:{xp:1,gold:308,pot:2}},
{id:'q36_ongi_camp_4',town:'ongi_camp',giver:'og_koko',lvl:41,kind:'추적',t:'눈 위의 옹기 표식',say:'저랑 같이 순례 온 친구가 먼저 설원 안쪽으로 들어갔는데 아직 안 돌아와요. 우리끼리는 길에 작은 옹기 조각을 놓아서 지나간 길을 표시하기로 했거든요. 그 조각들을 따라가 봐 주세요. 눈에 묻히기 전에요!',done:'신전 파수 기사가 친구를 침입자로 오해해서 붙잡고 있었대요! 친구 말로는, 옹기 조각을 떨어뜨리는 손이 떨려서 혼났대요. 찾아 줘서 정말 고마워요.',
 goals:[{type:'track',reg:'ongi',steps:[[200,700,'눈 위에 놓인 작은 옹기 조각. 코코가 말한 표식이다'],[225,1100,'옹기 조각 옆에 발자국이 둘. 하나는 무거운 쇠신 자국이다'],[250,1450,'옹기 조각이 밟혀 부서져 있다. 누군가 끌려간 자국이 이어진다'],[240,1800,'얼음 기둥 너머에서 「멈춰라, 침입자!」 하는 쩌렁쩌렁한 목소리가 들린다!']],foe:'og_2',foeN:'길을 막은 신전 파수 기사',d:'옹기 조각 표식 따라가 사라진 친구 찾기',n:5}],rw:{xp:.9,gold:332,pot:2}},
{id:'q36_ongi_camp_5',town:'ongi_camp',giver:'og_mira',req:'q36_ongi_camp_2',lvl:43,kind:'봉인',sig:1,t:'옹기여신의 다섯 손길',say:'설원 곳곳에 옹기여신의 손길이 새겨진 돌 다섯이 있어요. 흙 고르는 돌, 빚는 돌, 말리는 돌, 굽는 돌, 그리고 금 메우는 돌. 숭배자들이 돌을 흐려 놓아서 여신의 기운이 끊겼어요. 옹기 하나가 태어나 깨지고 다시 쓰이기까지의 차례 그대로 돌을 깨워 주세요. 흙을 고르고, 빚고, 말리고, 굽고, 깨진 뒤에는 금을 메우는 거예요.',done:'다섯 돌이 이어지자 동상 발치까지 따뜻한 흙빛이 번졌어요. 눈보라 속에서도 가마 불이 꺼지지 않는 까닭을 이제 알겠어요. 함께해 줘서 고마워요, 벗이여.',
 goals:[{type:'ritual',reg:'ongi',stones:[[300,900,'굽는 돌'],[330,1400,'흙 고르는 돌'],[270,1200,'금 메우는 돌'],[0,800,'빚는 돌'],[285,1700,'말리는 돌']],order:[1,3,4,0,2],hint:'흙 고르는 돌 · 빚는 돌 · 말리는 돌 · 굽는 돌 · 금 메우는 돌 (옹기가 태어나 다시 쓰이기까지)',mobs:['og_3','og_0'],d:'여신의 돌 다섯을 옹기 만드는 차례대로 깨우기'}],rw:{xp:1.2,gold:357,pot:3,tp:1}}
];

